(function(E){ const x = E["exam-10"] = E["exam-10"] || {units:{}}; (x.units = x.units || {})["x10-l3"] = {"id":"x10-l3","patterns":["L3-humanities","PARA-opinion","TR-ruledout","TR-paraphrase"],"title":{"en":"Listening Part 3: comparing study resources","tr":"Listening Part 3: çalışma kaynaklarını karşılaştırmak","fa":"Listening Part 3: مقایسه‌ی منابع درسی"},"objective":{"en":"In this lesson you will learn to follow two students comparing their experiences: answer single-choice questions on what each one says, then match five places to the comment the students really make about them.","tr":"Bu derste deneyimlerini karşılaştıran iki öğrenciyi takip etmeyi öğreneceksin: her birinin ne dediğiyle ilgili tek cevaplı soruları cevaplayacak, sonra beş yeri öğrencilerin onlar hakkında gerçekten yaptığı yorumla eşleştireceksin.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را که تجربه‌هایشان را مقایسه می‌کنند دنبال کنی: به سؤال‌های تک‌جوابی درباره‌ی حرف هرکدام جواب بدهی و بعد پنج مکان را با نظری که دانشجوها واقعاً درباره‌شان می‌دهند جور کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 3: comparing study resources","tr":"Listening Part 3: çalışma kaynaklarını karşılaştırmak","fa":"Listening Part 3: مقایسه‌ی منابع درسی"},"objective":{"en":"In this lesson you will learn to follow two students comparing their experiences: answer single-choice questions on what each one says, then match five places to the comment the students really make about them.","tr":"Bu derste deneyimlerini karşılaştıran iki öğrenciyi takip etmeyi öğreneceksin: her birinin ne dediğiyle ilgili tek cevaplı soruları cevaplayacak, sonra beş yeri öğrencilerin onlar hakkında gerçekten yaptığı yorumla eşleştireceksin.","fa":"در این درس یاد می‌گیری حرف‌های دو دانشجو را که تجربه‌هایشان را مقایسه می‌کنند دنبال کنی: به سؤال‌های تک‌جوابی درباره‌ی حرف هرکدام جواب بدهی و بعد پنج مکان را با نظری که دانشجوها واقعاً درباره‌شان می‌دهند جور کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Options in the box","tr":"Kutudaki seçenek","fa":"گزینه‌های کادر"},"value":"A-G"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: textbooks and where to find them","tr":"Bu sınav: ders kitapları ve nerede bulunacakları","fa":"این آزمون: کتاب‌های درسی و جای تهیه‌شان"},"intro":{"en":"Humanities, education and student life make up the largest group of Part 3 topics. Here the conversation is practical: two students share experiences and then judge several options for other students.","tr":"Beşerî bilimler, eğitim ve öğrenci hayatı Part 3 konularının en büyük grubunu oluşturur. Burada konuşma pratiktir: iki öğrenci deneyimlerini paylaşır ve sonra diğer öğrenciler için birkaç seçeneği değerlendirir.","fa":"علوم انسانی، آموزش و زندگی دانشجویی بزرگ‌ترین گروه موضوع‌های Part 3 است. این‌جا گفتگو عملی است: دو دانشجو تجربه‌هایشان را می‌گویند و بعد چند گزینه را برای دانشجوهای دیگر ارزیابی می‌کنند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x10-l3-ctx","exam":true,"patterns":["L3-humanities","PARA-opinion"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Two students compare ways of getting books","tr":"İki öğrenci kitap edinme yollarını karşılaştırıyor","fa":"دو دانشجو راه‌های تهیه‌ی کتاب را مقایسه می‌کنند"},"asks":{"en":"Two students talk about their experiences of buying, borrowing and sharing books, then comment on five places where new students can get them. Single-choice questions come first, then a box of seven comments for five places.","tr":"İki öğrenci kitap satın alma, ödünç alma ve paylaşma deneyimlerini anlatıyor, sonra yeni öğrencilerin kitap bulabileceği beş yer hakkında yorum yapıyor. Önce tek cevaplı sorular, sonra beş yer için yedi yorumlu bir kutu geliyor.","fa":"دو دانشجو درباره‌ی تجربه‌شان از خریدن، امانت گرفتن و شریک شدن کتاب حرف می‌زنند و بعد درباره‌ی پنج جایی که دانشجوهای تازه می‌توانند کتاب تهیه کنند نظر می‌دهند. اول سؤال‌های تک‌جوابی، بعد یک کادر با هفت نظر برای پنج مکان."},"fields":["Buying a new book","E-books","Second-hand books","Sharing","What the university could do","Five places and one comment on each"],"words":[{"a":"on loan","b":"always out / borrowed by someone else","tr":"ödünç verilmiş","fa":"امانت داده‌شده"},{"a":"the latest edition","b":"the new version of the book","tr":"en son baskı","fa":"آخرین چاپ"},{"a":"that wasn’t the problem","b":"the real reason was","tr":"sorun o değildi","fa":"مشکل آن نبود"},{"a":"tiring to read","b":"my eyes get tired / gives me a headache","tr":"okuması yorucu","fa":"خواندنش خسته‌کننده"},{"a":"nearby","b":"in the same building / close by","tr":"yakında","fa":"نزدیک"},{"a":"online","b":"on the course website / scanned","tr":"çevrimiçi","fa":"آنلاین"},{"a":"useful advice","b":"they’ll tell you which edition is fine","tr":"faydalı tavsiye","fa":"راهنمایی مفید"},{"a":"only at the start of term","b":"in the first week / after that it’s all gone","tr":"yalnızca dönem başında","fa":"فقط اول ترم"},{"a":"often closed","b":"shuts early / not open at weekends","tr":"çoğu zaman kapalı","fa":"اغلب بسته"},{"a":"a good choice","b":"a much better selection","tr":"iyi bir seçenek yelpazesi","fa":"انتخاب خوب"},{"a":"too far away","b":"miles away / two buses to get there","tr":"çok uzak","fa":"خیلی دور"}],"traps":[{"en":"A reason is mentioned and then put aside: \"they’re always out, but that wasn’t really the problem.\" The answer is the reason that follows.","tr":"Bir neden söylenip bir kenara bırakılır: \"hep ödünçteler ama asıl sorun o değildi.\" Cevap ardından gelen nedendir.","fa":"دلیلی گفته و کنار گذاشته می‌شود: «همیشه امانت‌اند، اما مشکل اصلی این نبود». جواب دلیلی است که بعدش می‌آید."},{"en":"A good point comes before the problem: \"It’s got a huge collection... The trouble is...\" For a place, choose the comment the speakers stress.","tr":"Sorundan önce iyi bir nokta gelir: \"Çok büyük bir koleksiyonu var... Sorun şu ki...\" Bir yer için konuşanların vurguladığı yorumu seç.","fa":"نکته‌ی خوب قبل از مشکل می‌آید: «مجموعه‌ی بزرگی دارد... مشکل این است که...». برای هر مکان، نظری را انتخاب کن که گوینده‌ها رویش تأکید می‌کنند."},{"en":"Seven comments, five places: two comments are never the answer, even if one is mentioned (\"people from other universities seem to go there\").","tr":"Yedi yorum, beş yer: iki yorum asla cevap değildir, biri söylense bile (\"başka üniversitelerden insanlar oraya gidiyor gibi\").","fa":"هفت نظر، پنج مکان: دو نظر هرگز جواب نیستند، حتی اگر از یکی‌شان حرف زده شود («انگار دانشجوهای دانشگاه‌های دیگر آن‌جا می‌روند»)."}],"example":{"lines":[["Student","The museum café is lovely, and people say it’s expensive, but actually it’s cheaper than most places in town. The only problem is the queue."]],"item":"What do they say about the museum café? A It is expensive.  B It is good value.","answer":"B","why":{"en":"\"People say it’s expensive\" is ruled out by \"actually it’s cheaper\": good value.","tr":"\"İnsanlar pahalı diyor\" ifadesi \"aslında daha ucuz\" ile eleniyor: fiyatına göre iyi.","fa":"«مردم می‌گویند گران است» با «در واقع ارزان‌تر است» رد می‌شود: به‌صرفه است."}}},{"id":"L3-edu","ctx":["L3-edu","L3-humanities"],"title":{"en":"Study skills, placements and careers","tr":"Çalışma becerileri, stajlar ve kariyer","fa":"مهارت مطالعه، کارآموزی و مسیر شغلی"},"asks":{"en":"Two students, sometimes with a tutor, plan or review a project on a work placement, teaching practice, a library or career plans. Questions ask what they decide, what they think of a source or a method, what went wrong and what they will do next.","tr":"İki öğrenci, bazen bir hocayla, bir staj, öğretmenlik uygulaması, bir kütüphane ya da kariyer planları üzerine bir projeyi planlar ya da değerlendirir. Sorular neye karar verdiklerini, bir kaynak ya da yöntem hakkında ne düşündüklerini, neyin ters gittiğini ve sırada ne yapacaklarını sorar.","fa":"دو دانشجو، گاهی با یک استاد، پروژه‌ای درباره‌ی یک کارآموزی، تمرین تدریس، یک کتابخانه یا برنامه‌های شغلی را برنامه‌ریزی یا بررسی می‌کنند. سؤال‌ها می‌پرسند به چه تصمیمی می‌رسند، درباره‌ی یک منبع یا روش چه فکر می‌کنند، چه چیزی خراب شد و قدم بعدی‌شان چیست."},"fields":["What did the student find most useful about the placement?","What does the tutor advise?","Which TWO skills does the student want to improve?","What is the student’s plan after the course?"],"words":[{"a":"placement","b":"time working in a real job during the course","tr":"staj","fa":"کارآموزی"},{"a":"tutor","b":"the teacher who supervises you","tr":"danışman hoca","fa":"استاد راهنما"},{"a":"feedback","b":"comments on your work","tr":"geri bildirim","fa":"بازخورد"},{"a":"assignment","b":"the piece of written work","tr":"ödev","fa":"تکلیف"},{"a":"deadline","b":"the date you must hand it in","tr":"son teslim tarihi","fa":"مهلت تحویل"},{"a":"reflect on","b":"think about what you learned","tr":"üzerine düşünmek","fa":"تأمل کردن درباره‌ی"},{"a":"case study","b":"one real example in detail","tr":"vaka çalışması","fa":"مطالعه‌ی موردی"},{"a":"confidence","b":"believing you can do it","tr":"özgüven","fa":"اعتمادبه‌نفس"},{"a":"time management","b":"organising your hours","tr":"zaman yönetimi","fa":"مدیریت زمان"},{"a":"supervisor","b":"the person in charge of you at work","tr":"iş yerindeki sorumlu","fa":"سرپرست"},{"a":"career","b":"the job you want long-term","tr":"kariyer","fa":"مسیر شغلی"},{"a":"appendix","b":"extra pages at the end of a report","tr":"ek","fa":"پیوست"}],"traps":[{"en":"Tutor and student can disagree. The question may ask for the tutor’s view, not the student’s.","tr":"Hoca ve öğrenci aynı fikirde olmayabilir. Soru öğrencinin değil hocanın görüşünü sorabilir.","fa":"استاد و دانشجو ممکن است هم‌نظر نباشند. سؤال شاید نظر استاد را بخواهد، نه دانشجو."},{"en":"\"Most useful\" and \"most enjoyable\" are different questions about the same placement.","tr":"\"En faydalı\" ile \"en keyifli\" aynı staj hakkında iki ayrı sorudur.","fa":"«مفیدترین» و «لذت‌بخش‌ترین» دو سؤال متفاوت درباره‌ی همان کارآموزی‌اند."}],"example":{"lines":[["Tutor","What did you get most out of?"],["Student","Well, I loved working with the animals."],["Student","But honestly, the most useful thing was watching how the vets talked to worried owners."]],"item":"What was most useful for the student?  A working with animals   B learning how to talk to owners   C using the equipment","answer":"B","why":{"en":"Working with animals was enjoyable. \"The most useful thing\" was watching the vets talk to owners.","tr":"Hayvanlarla çalışmak keyifliydi. \"En faydalı şey\" veterinerlerin sahiplerle konuşmasını izlemekti.","fa":"کار با حیوان‌ها لذت‌بخش بود. «مفیدترین چیز» دیدن طرز حرف زدن دامپزشک‌ها با صاحبان حیوان بود."}},"general":true,"patterns":["L3-humanities"],"often":{"pattern":"L3-humanities","n":21,"of":40,"label":{"en":"Comes up often in the real exam: 21 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 21’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۱ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Five choices, then a box of seven","tr":"Beş seçim, sonra yedili bir kutu","fa":"پنج سؤال، بعد یک کادر هفت‌تایی"},"body":{"en":"Questions 21-25: choose A, B or C. Questions 26-30: match five places to seven comments, A-G, using each letter once; two letters are left over. The conversation follows the order of the questions.","tr":"Soru 21-25: A, B ya da C’yi seç. Soru 26-30: beş yeri yedi yorumla (A-G) eşleştir, her harfi bir kez kullan; iki harf artar. Konuşma soruların sırasını izler.","fa":"سؤال‌های ۲۱ تا ۲۵: A، B یا C را انتخاب کن. سؤال‌های ۲۶ تا ۳۰: پنج مکان را با هفت نظر (A تا G) جور کن و هر حرف را یک بار به کار ببر؛ دو حرف می‌مانند. گفتگو به ترتیب سؤال‌ها جلو می‌رود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Four steps","tr":"Dört adım","fa":"چهار قدم"},"steps":[{"en":"Underline the speaker and the key idea in each question: \"Why did Keira buy...\", \"What does Tom say about...\".","tr":"Her sorudaki konuşanın ve ana fikrin altını çiz: \"Why did Keira buy...\", \"What does Tom say about...\".","fa":"زیر گوینده و ایده‌ی اصلی هر سؤال خط بکش: «Why did Keira buy...»، «What does Tom say about...»."},{"en":"Expect each option to be mentioned; listen for which one the speaker says matters.","tr":"Her seçenekten söz edilmesini bekle; konuşanın hangisinin önemli olduğunu söylediğine kulak ver.","fa":"انتظار داشته باش از همه‌ی گزینه‌ها حرف زده شود؛ گوش بده گوینده کدام را مهم می‌داند."},{"en":"For the box, the place name starts each answer; the comment can come before or after a \"but\".","tr":"Kutu için her cevap yerin adıyla başlar; yorum bir \"but\"tan önce ya da sonra gelebilir.","fa":"برای کادر، هر جواب با اسم مکان شروع می‌شود؛ نظر ممکن است قبل یا بعد از «but» بیاید."},{"en":"Cross out each letter you use; check the two unused letters are really not stated.","tr":"Kullandığın her harfin üstünü çiz; kullanılmayan iki harfin gerçekten söylenmediğini kontrol et.","fa":"هر حرفی را که به کار بردی خط بزن؛ مطمئن شو دو حرف باقی‌مانده واقعاً گفته نشده‌اند."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"A true detail, but not the point","tr":"Doğru bir ayrıntı ama asıl nokta değil","fa":"جزئیاتِ درست، اما نه نکته‌ی اصلی"},"table":{"headers":{"en":["You hear","It means"],"tr":["Duyduğun","Anlamı"],"fa":["می‌شنوی","یعنی"]},"rows":[["that wasn’t really the problem","the real reason comes next"],["it’s not cheap, but the staff are brilliant","the comment is about the staff"],["Maybe, but it’s miles away","the distance is the comment"],["They came really quickly","late delivery is ruled out"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One box answer, step by step","tr":"Bir kutu cevabı, adım adım","fa":"یک جواب کادر، قدم به قدم"},"instruction":"What do the students say about the sports centre? Choose from the box.","item":"Box: A It has new equipment.  B It is very crowded.  C It is too expensive.","lines":[["Student","The equipment’s all new, which is great. But you can never get on a machine after four o’clock; the whole university seems to be there."]],"answer":"B","walk":[{"en":"A is true but comes before \"But\".","tr":"A doğru ama \"But\"tan önce geliyor.","fa":"A درست است، اما قبل از «But» می‌آید."},{"en":"After \"But\": you can never get on a machine; the whole university is there.","tr":"\"But\"tan sonra: hiçbir aletin başına geçemiyorsun; bütün üniversite orada.","fa":"بعد از «But»: هیچ‌وقت نوبت دستگاه نمی‌رسد؛ کل دانشگاه آن‌جاست."},{"en":"The point the student stresses is the crowds: B.","tr":"Öğrencinin vurguladığı nokta kalabalık: B.","fa":"نکته‌ای که دانشجو رویش تأکید می‌کند شلوغی است: B."}]},"quick":{"prompt":"\"The café near the library is a bit noisy, and it’s not cheap. But it’s the only place on campus that’s open until midnight.\" What is the student’s main point?","options":["It stays open late.","It is noisy.","It is expensive."],"correct":0,"why":{"en":"Noise and price come first; \"But it’s the only place... open until midnight\" is the point.","tr":"Gürültü ve fiyat önce geliyor; asıl nokta \"Ama gece yarısına kadar açık tek yer\".","fa":"سروصدا و قیمت اول می‌آیند؛ «اما تنها جایی است که تا نیمه‌شب باز است» نکته‌ی اصلی است."}},"remember":{"en":"Find whose view the question asks for, and choose the point the speaker stresses after \"but\".","tr":"Sorunun kimin görüşünü sorduğunu bul ve konuşanın \"but\"tan sonra vurguladığı noktayı seç.","fa":"پیدا کن سؤال نظر چه کسی را می‌خواهد و نکته‌ای را انتخاب کن که گوینده بعد از «but» رویش تأکید می‌کند."},"type":"explain","id":"c-x10-l3-e","course":"ielts-exams","exam":"exam-10","unit":"x10-l3"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 3","title":{"en":"Borrowing and buying textbooks","tr":"Ders kitabı ödünç almak ve satın almak","fa":"امانت گرفتن و خریدن کتاب درسی"},"timed":7,"ctx":["L3-humanities"],"script":[{"who":"Tom","line":"Keira, is that a brand-new statistics book? I thought you always borrowed everything from the library."},{"who":"Keira","line":"I usually do. And the library does have a few copies, though they're always out, of course. But that wasn't really the problem. The library only has the second edition, and the lecturer said the new edition has completely different exercises, and that's what we'll be tested on. So I had to buy it."},{"who":"Tom","line":"Fair enough. I've been reading most of my books as e-books this year. They're cheaper, usually, though not always."},{"who":"Keira","line":"Do you like them?"},{"who":"Tom","line":"For looking things up, they're great. You can search for a word in seconds. But I can't read them for more than half an hour without getting a headache. My eyes just get tired on a screen. And you can't lend an e-book to a friend, which is a shame."},{"who":"Keira","line":"Same here. What about the second-hand ones you ordered online last month? Were they all right?"},{"who":"Tom","line":"Mixed. They came really quickly, which surprised me, and they were cheap. But two of them were covered in someone else's notes, in pen, all down the margins. It's really distracting when you're trying to work out what's important. Next time I'll check the description more carefully. Some sellers do mention it, if you read the small print."},{"who":"Keira","line":"That's annoying. You could try sharing with someone. Priyanka and I shared a history book last term."},{"who":"Tom","line":"Did it work?"},{"who":"Keira","line":"Mostly, because she lives in the same building as me, so it was easy to pass it back and forth. I tried it with someone on the other side of the city once, and it was hopeless. We never had the book when we needed it."},{"who":"Tom","line":"I can see that. Honestly, I think the university should do more about all this. Books are so expensive."},{"who":"Keira","line":"I agree. They could buy more copies for the library, but there's never enough space, and they'd always be out anyway. What I'd really like is for them to scan the essential chapters and put them on the course website. That way everyone gets them, and nobody has to buy the whole book for two chapters."},{"who":"Tom","line":"That would make a big difference. Anyway, I'm making a list of places to get books for the new students' guide. Can you help me with comments?"},{"who":"Keira","line":"Sure. It's a good idea, because nobody told us any of this when we started. Start with the campus bookshop."},{"who":"Tom","line":"Well, it's not cheap. Prices have actually gone up this year. But the people who work there are brilliant. They know which books each department recommends, and they'll tell you if a cheaper edition is fine for your course."},{"who":"Keira","line":"Yes, they're really helpful. What about the book sale the student union runs?"},{"who":"Tom","line":"It can be good, but it's really only worth going in the first week of term. After that, all the useful books have gone, and it's just old novels and out-of-date guides."},{"who":"Keira","line":"Then there's the city library. It's got a huge collection."},{"who":"Tom","line":"It has, and the building's lovely. The trouble is the opening hours. It closes at five most days and isn't open on Sundays, which is exactly when most of us want to study. I went there twice last month and both times I arrived just as they were locking the doors."},{"who":"Keira","line":"True. And that charity shop on Market Street?"},{"who":"Tom","line":"I love that place. It's not very organised, but if you're looking for older books, classic novels or plays, it's got a much better selection than anywhere else. I found three of the books on our literature list there for a pound each."},{"who":"Keira","line":"And finally, the book warehouse on the ring road. People from other universities seem to go there."},{"who":"Tom","line":"Maybe, but it's miles away. Unless you've got a car, it takes two buses to get there, so for most students it isn't worth the trip."},{"who":"Keira","line":"OK, I think that's a good list. Shall we write it up this evening?"},{"who":"Tom","line":"Let's do it after the seminar tomorrow. I'm out of energy today."}],"groups":[{"instruction":"Questions 21-25. Choose the correct letter, A, B or C.","qtype":"mcq","questions":[{"n":21,"kind":"mcq","prompt":"Why did Keira buy a new copy of the statistics textbook?","options":["A The library copies were always on loan.","B She needed the latest edition.","C She wanted to write notes in it."],"correct":1,"evidence":"The library only has the second edition","why":{"en":"The copies are \"always out\", but \"that wasn’t really the problem\": the library only has the old edition.","tr":"Kopyalar \"hep ödünçte\", ama \"asıl sorun bu değildi\": kütüphanede yalnızca eski baskı var.","fa":"نسخه‌ها «همیشه امانت‌اند»، اما «مشکل اصلی این نبود»: کتابخانه فقط چاپ قدیمی را دارد."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":22,"kind":"mcq","prompt":"What does Tom say about e-books?","options":["A They make his eyes tired after a while.","B They always cost less than printed books.","C They are difficult to search."],"correct":0,"evidence":"My eyes just get tired on a screen","why":{"en":"Searching is \"great\", and they are cheaper only \"usually, though not always\". Reading for long gives him a headache.","tr":"Arama yapmak \"harika\", ve \"genelde ama her zaman değil\" daha ucuzlar. Uzun okumak başını ağrıtıyor.","fa":"جستجو «عالی است» و فقط «معمولاً، نه همیشه» ارزان‌ترند. خواندن طولانی سرش را به درد می‌آورد."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":23,"kind":"mcq","prompt":"What problem did Tom have with the second-hand books he ordered?","options":["A They arrived late.","B They were more expensive than expected.","C Someone had written in them."],"correct":2,"evidence":"two of them were covered in someone else's notes","why":{"en":"They came \"really quickly\" and were cheap; the problem was another person’s notes in pen.","tr":"\"Çok çabuk\" geldiler ve ucuzdular; sorun başkasının tükenmez kalemle yazdığı notlardı.","fa":"«خیلی زود» رسیدند و ارزان بودند؛ مشکل یادداشت‌های خودکاری کس دیگری بود."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":24,"kind":"mcq","prompt":"What does Keira say about sharing books?","options":["A It is easier when the other person lives nearby.","B It often causes arguments.","C Tutors do not allow it."],"correct":0,"evidence":"she lives in the same building as me","why":{"en":"It worked with someone in her building, and was \"hopeless\" with someone across the city.","tr":"Aynı binada oturan biriyle işe yaradı, şehrin öbür ucundaki biriyle \"umutsuzdu\".","fa":"با کسی که در همان ساختمان بود جواب داد و با کسی در آن سر شهر «بی‌فایده» بود."},"trap":["TR-paraphrase"]},{"n":25,"kind":"mcq","prompt":"What would Keira like the university to do?","options":["A buy more library copies","B make key chapters available online","C reduce prices in the campus bookshop"],"correct":1,"evidence":"scan the essential chapters and put them on the course website","why":{"en":"More copies would have no space and \"always be out anyway\". She wants essential chapters on the course website.","tr":"Daha fazla kopya için yer yok ve \"zaten hep ödünçte olur\". Temel bölümlerin ders sitesine konmasını istiyor.","fa":"نسخه‌ی بیشتر جا ندارد و «به‌هرحال همیشه امانت است». می‌خواهد فصل‌های اصلی روی سایت درس گذاشته شوند."},"trap":["TR-ruledout","TR-paraphrase"]}]},{"instruction":"Questions 26-30. What do the students say about each of the following places to get books? Choose FIVE answers from the box and write the correct letter, A-G, next to Questions 26-30.","qtype":"matching","bank":["A It is cheaper than it used to be.","B The staff give useful advice.","C It is only worth visiting at the start of term.","D It is too far away for most students.","E It has a good choice of older books.","F It is often closed when students need it.","G It is popular with students from other universities."],"questions":[{"n":26,"kind":"match","prompt":"the campus bookshop","correct":1,"evidence":"the people who work there are brilliant","why":{"en":"Prices have gone up (A is wrong); the staff know what each department recommends.","tr":"Fiyatlar arttı (A yanlış); personel her bölümün ne önerdiğini biliyor.","fa":"قیمت‌ها بالا رفته (A غلط است)؛ کارکنان می‌دانند هر رشته چه کتابی توصیه می‌کند."},"trap":["TR-ruledout","TR-paraphrase"]},{"n":27,"kind":"match","prompt":"the student union book sale","correct":2,"evidence":"it's really only worth going in the first week of term","why":{"en":"\"Only worth going in the first week of term\" = only worth visiting at the start.","tr":"\"Yalnızca dönemin ilk haftasında gitmeye değer\" = yalnızca başta gitmeye değer.","fa":"«فقط در هفته‌ی اول ترم ارزش رفتن دارد» یعنی فقط اول ترم."},"trap":["TR-paraphrase"]},{"n":28,"kind":"match","prompt":"the city library","correct":5,"evidence":"The trouble is the opening hours","why":{"en":"A huge collection and a lovely building, but it closes at five and on Sundays, when students study.","tr":"Büyük bir koleksiyon ve güzel bir bina, ama saat beşte ve pazar günleri kapalı; öğrencilerin çalıştığı saatler.","fa":"مجموعه‌ای بزرگ و ساختمانی زیبا، اما ساعت پنج و یکشنبه‌ها بسته است، درست وقتی دانشجوها درس می‌خوانند."},"trap":["TR-paraphrase"]},{"n":29,"kind":"match","prompt":"the charity shop on Market Street","correct":4,"evidence":"it's got a much better selection than anywhere else","why":{"en":"For \"older books, classic novels or plays\" it has \"a much better selection\".","tr":"\"Eski kitaplar, klasik romanlar ya da oyunlar\" için \"çok daha iyi bir seçki\" var.","fa":"برای «کتاب‌های قدیمی، رمان‌های کلاسیک یا نمایشنامه» «انتخاب خیلی بهتری» دارد."},"trap":["TR-paraphrase"]},{"n":30,"kind":"match","prompt":"the book warehouse on the ring road","correct":3,"evidence":"for most students it isn't worth the trip","why":{"en":"Students from other universities go there, but that is not the point: \"it’s miles away\". G is a distractor.","tr":"Başka üniversitelerden öğrenciler gidiyor ama mesele bu değil: \"kilometrelerce uzakta\". G çeldirici.","fa":"دانشجوهای دانشگاه‌های دیگر آن‌جا می‌روند، اما نکته این نیست: «فرسنگ‌ها دور است». G گزینه‌ی انحرافی است."},"trap":["TR-ruledout","TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Keira":{"accent":"North American","gender":"F","tts":{"engine":"kokoro","voice":"af_heart"},"role":"Student"},"Tom":{"accent":"British (Southern English)","gender":"M","tts":{"engine":"kokoro","voice":"bm_daniel"},"role":"Student"}},"sequence":[{"type":"announcer","text":"Part 3. You will hear two students, Keira and Tom, talking about how they get the books they need for their courses. First, you have some time to look at Questions 21 to 25."},{"type":"pause","seconds":30,"note":"reading time, Questions 21-25"},{"type":"announcer","text":"Now listen carefully and answer Questions 21 to 25."},{"type":"sfx","note":"university corridor, light footsteps in the background"},{"type":"lines","from":0,"to":11},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 26 to 30."},{"type":"pause","seconds":30,"note":"reading time, Questions 26-30"},{"type":"announcer","text":"Now listen and answer Questions 26 to 30."},{"type":"lines","from":12,"to":24},{"type":"announcer","text":"That is the end of Part 3. You now have half a minute to check your answers.","after":30}]},"id":"c-x10-l3-d","course":"ielts-exams","exam":"exam-10","unit":"x10-l3"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The library copies are always out.\" Out means...","options":["thrown away","out of date","borrowed by other people"],"correct":2,"why":{"en":"For library books, \"out\" = on loan to someone else.","tr":"Kütüphane kitapları için \"out\" = başkasına ödünç verilmiş.","fa":"برای کتاب کتابخانه، «out» یعنی دست کس دیگری امانت است."}},{"tests":"paraphrase","point":3,"prompt":"Box: \"It is often closed when students need it.\" Which sentence in a recording matches it?","options":["It’s a long way from the campus.","The trouble is it shuts at five and on Sundays.","The staff are not very friendly."],"correct":1,"why":{"en":"Closing at five and on Sundays = often closed when students want to go.","tr":"Saat beşte ve pazar günleri kapanması = öğrencilerin istediği zaman çoğu kez kapalı.","fa":"بسته شدن ساعت پنج و یکشنبه‌ها یعنی اغلب وقتی دانشجوها می‌خواهند بروند بسته است."}},{"tests":"method","point":2,"prompt":"Questions 26-30 have five places and seven letters. What does this tell you?","options":["Two letters will not be used","Two places share a letter","Every letter is used"],"correct":0,"why":{"en":"\"Choose FIVE answers\" from seven: two letters are left over.","tr":"Yediden \"BEŞ cevap seç\": iki harf artar.","fa":"«پنج جواب انتخاب کن» از هفت حرف: دو حرف می‌ماند."}},{"tests":"trap","point":3,"prompt":"\"Plenty of people use the online shop, but for me the problem is that the books take weeks to arrive.\" What is the speaker’s comment on the online shop?","options":["It is very popular.","It is cheap.","Delivery is slow."],"correct":2,"why":{"en":"Popularity comes before \"but\"; the speaker’s comment is the slow delivery.","tr":"Popülerlik \"but\"tan önce geliyor; konuşanın yorumu teslimatın yavaşlığı.","fa":"محبوبیت قبل از «but» می‌آید؛ نظر گوینده کندیِ ارسال است."}}],"id":"c-x10-l3-x","course":"ielts-exams","exam":"exam-10","unit":"x10-l3"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
